with exploded as (select id, service, host, log_ts, level, latency_ms, status_code, key, attr_value from app_logs lateral view outer explode(context) e as key, attr_value), parsed as (select id, log_ts, level, status_code, cast((status_code & 8) != 0 as int) as flag_bit8, shiftright(status_code, 2) as status_code_high from exploded), metrics as (select log_ts, status_code, status_code_high, max(status_code_high) over (partition by level) as level_max_status_code_high, count(flag_bit8) over (partition by level order by cast(log_ts as bigint) range between 7200 preceding and current row) as flag_bit8_count_2h from parsed), scored as (select status_code, level_max_status_code_high, rank() over (order by flag_bit8_count_2h desc nulls first) as flag_bit8_count_2h_rank, percent_rank() over (order by level_max_status_code_high nulls last) as level_max_status_code_high_percent_rank, count(status_code) over (order by cast(log_ts as bigint) range between 900 preceding and current row) as status_code_count_15m from metrics) select case when level_max_status_code_high >= 3 then 'PREMIUM' else 'STANDARD' end as level_max_status_code_high_tier, case when level_max_status_code_high_percent_rank >= 0.88 then 'HIGH' else 'LOW' end as level_max_status_code_high_percent_rank_tier, bit_and(status_code) as status_code_bit_and, bit_or(status_code) as status_code_bit_or, rank() over (partition by case when level_max_status_code_high >= 3 then 'PREMIUM' else 'STANDARD' end order by bit_or(status_code) desc) as status_code_bit_or_rank from scored group by level_max_status_code_high_tier, level_max_status_code_high_percent_rank_tier having status_code_bit_and >= 1 order by status_code_bit_or desc nulls first
